<?php
require 'page-guard.php';require '../config/db_conn.php';$section=$_SESSION['teacher-section'];$date=$_GET['date']??date('Y-m-d');$student=trim($_GET['student']??'');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))exit('Invalid date.');$stmt=$conn->prepare("SELECT a.STUDENT_ID,COALESCE(s.STUDENT_NAME,a.STUDENT_NAME) STUDENT_NAME,a.TIME_IN FROM attendance a INNER JOIN students s ON TRIM(a.STUDENT_ID)=TRIM(s.STUDENT_ID) WHERE s.SECTION=? AND DATE(a.TIME_IN)=? AND (?='' OR a.STUDENT_ID=?) ORDER BY STUDENT_NAME");$stmt->bind_param('ssss',$section,$date,$student,$student);$stmt->execute();$result=$stmt->get_result();if($result->num_rows):while($row=$result->fetch_assoc()):$time=new DateTime($row['TIME_IN']);?><tr><td class="px-4 py-4"><?= htmlspecialchars($row['STUDENT_ID']) ?></td><td class="px-4 py-4 font-bold"><?= htmlspecialchars($row['STUDENT_NAME']) ?></td><td class="px-4 py-4"><?= $time->format('F j, Y') ?></td><td class="px-4 py-4"><?= $time->format('g:i A') ?></td><td class="px-4 py-4"><span class="rounded-full bg-emerald-50 px-3 py-1 text-xs font-bold text-emerald-700">Present</span></td></tr><?php endwhile;else:?><tr><td colspan="5" class="px-4 py-10 text-center text-slate-500">No attendance records found.</td></tr><?php endif; ?>